{
  "nombre": "Sentadilla",
  "descripcion": "Ejercicio compuesto para cuádriceps, glúteos e isquiotibiales. Desciende con la espalda recta hasta que los muslos queden paralelos al suelo.",
  "imagen": "https://images.unsplash.com/photo-1584735935682-2f2b69dff9d2?w=600&q=80"
}

{
  "nombre": "Press de Banca",
  "descripcion": "Ejercicio de empuje horizontal para pecho, hombros anteriores y tríceps. Mantén los omóplatos retraídos durante todo el movimiento.",
  "imagen": "https://images.unsplash.com/photo-1534438327276-14e5300c3a48?w=600&q=80"
}

{
  "nombre": "Peso Muerto",
  "descripcion": "Movimiento de bisagra de cadera que trabaja toda la cadena posterior. Mantén la barra pegada al cuerpo y la espalda neutra.",
  "imagen": "https://images.unsplash.com/photo-1517963879433-6ad2b056d712?w=600&q=80"
}

{
  "nombre": "Dominadas",
  "descripcion": "Ejercicio de tracción vertical con el propio peso corporal. Trabaja dorsal ancho, bíceps y parte media de la espalda.",
  "imagen": "https://images.unsplash.com/photo-1598971639058-a13e98c20c08?w=600&q=80"
}

{
  "nombre": "Press Militar",
  "descripcion": "Empuje vertical con barra o mancuernas para deltoides, tríceps y trapecio superior. Evita arquear la zona lumbar.",
  "imagen": "https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?w=600&q=80"
}

{
  "nombre": "Remo con Barra",
  "descripcion": "Tracción horizontal para dorsal ancho, romboides y bíceps. Inclina el torso a 45° y lleva la barra al abdomen.",
  "imagen": "https://images.unsplash.com/photo-1540497077202-7c8a3999166f?w=600&q=80"
}

{
  "nombre": "Zancadas",
  "descripcion": "Ejercicio unilateral de piernas que trabaja cuádriceps y glúteos. Mantén el torso erguido y la rodilla delantera sobre el pie.",
  "imagen": "https://images.unsplash.com/photo-1434608519344-49d77a699e1d?w=600&q=80"
}

{
  "nombre": "Plancha Abdominal",
  "descripcion": "Ejercicio isométrico de core. Apoya antebrazos y puntas de pie, mantén el cuerpo alineado sin hundir las caderas.",
  "imagen": "https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=600&q=80"
}

{
  "nombre": "Curl de Bíceps",
  "descripcion": "Ejercicio de aislamiento para bíceps con barra o mancuernas. Controla el descenso y evita balancear el torso.",
  "imagen": "https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?w=600&q=80"
}

{
  "nombre": "Burpee",
  "descripcion": "Ejercicio funcional de cuerpo completo que combina sentadilla, plancha, flexión y salto. Ideal para cardio y resistencia muscular.",
  "imagen": "https://images.unsplash.com/photo-1517344884509-a0c97ec11bcc?w=600&q=80"
}
